import fs from 'node:fs/promises';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { pathToFileURL } from 'node:url';

/** PCM generated by FusionKit's bounded review normalizer, never the NAS original. */
export function summarizeReviewWav(buffer, bins = 900) {
  if (buffer.toString('ascii', 0, 4) !== 'RIFF' || buffer.toString('ascii', 8, 12) !== 'WAVE') throw Error('Expected RIFF/WAVE');
  let format, data;
  for (let offset = 12; offset + 8 <= buffer.length;) {
    const size = buffer.readUInt32LE(offset + 4);
    const start = offset + 8;
    if (start + size > buffer.length) throw Error('Truncated WAV chunk');
    const name = buffer.toString('ascii', offset, offset + 4);
    if (name === 'fmt ') format = buffer.subarray(start, start + size);
    if (name === 'data') data = buffer.subarray(start, start + size);
    offset = start + size + (size % 2);
  }
  if (!format || format.length < 16 || format.readUInt16LE(0) !== 1 || format.readUInt16LE(2) !== 1 || format.readUInt32LE(4) !== 16000 || format.readUInt16LE(14) !== 16 || !data || !data.length || data.length % 2) throw Error('Review WAV must be mono PCM16 at 16 kHz');
  if (!Number.isSafeInteger(bins) || bins < 1 || bins > 5000) throw Error('Invalid waveform bin count');
  const samples = data.length / 2;
  const peaks = Array.from({ length: Math.min(bins, samples) }, (_, index) => {
    let peak = 0;
    const start = Math.floor(index * samples / Math.min(bins, samples));
    const end = Math.floor((index + 1) * samples / Math.min(bins, samples));
    for (let sample = start; sample < end; sample++) peak = Math.max(peak, Math.abs(data.readInt16LE(sample * 2)) / 32768);
    return Math.round(peak * 10000) / 10000;
  });
  return { durationMs: samples / 16, peaks };
}

export function validateReviewRegions(regions, clips) {
  const ids = new Set();
  if (!Array.isArray(regions) || !regions.length || regions.length > 200) throw Error('Invalid review regions');
  for (const region of regions) {
    const clip = clips.find(item => item.id === region.clipId);
    if (typeof region.id !== 'string' || !region.id || ids.has(region.id) || !clip ||
        !Number.isFinite(region.startMs) || !Number.isFinite(region.endMs) || region.startMs < 0 || region.endMs <= region.startMs || region.endMs > clip.durationMs || typeof region.reason !== 'string') throw Error('Invalid review region');
    ids.add(region.id);
  }
  if (clips.some(clip => !regions.some(region => region.clipId === clip.id))) throw Error('Every clip needs a review region');
}

export function importReviewAnnotations(report, datasetId, clips, regions) {
  if (!report) return {};
  if (![1, 2].includes(report.schemaVersion) || report.datasetId !== datasetId ||
      !Array.isArray(report.clips) || report.clips.length !== clips.length ||
      !Array.isArray(report.regions) || report.regions.length !== regions.length) throw Error('Annotation dataset mismatch');
  for (const [index, clip] of clips.entries()) {
    const supplied = report.clips[index];
    if (!supplied || ['id','sha256','durationMs','sourceStartMs'].some(key=>supplied[key] !== clip[key])) throw Error('Annotation clip mismatch');
  }
  const annotations = {};
  for (const [index, region] of regions.entries()) {
    const supplied = report.regions[index];
    if (!supplied || ['id','clipId','startMs','endMs'].some(key=>supplied[key] !== region[key]) ||
        !['unreviewed','speech','non_speech','uncertain'].includes(supplied.verdict) ||
        typeof supplied.note !== 'string' || supplied.note.length > 4000) throw Error('Invalid annotation region');
    const playback = report.schemaVersion === 2 ? supplied.lastPlaybackRequest : null;
    const clip = clips.find(item => item.id === region.clipId);
    if (playback && (playback.evidence !== 'playback_request_only' ||
        ![0,1000,2000].includes(playback.paddingMs) || ![1,.8,.65].includes(playback.rate) ||
        !['requested','started','failed'].includes(playback.status) || typeof playback.requestedAt !== 'string' ||
        playback.requestedAt.length > 64 ||
        playback.startMs !== Math.round(Math.max(0,region.startMs-playback.paddingMs)) ||
        playback.endMs !== Math.round(Math.min(clip.durationMs,region.endMs+playback.paddingMs)))) throw Error('Invalid playback request');
    // v1 judgments never acquire invented playback history; v2 requests are not heard-range evidence.
    annotations[region.id] = {verdict: supplied.verdict, note: supplied.note, lastPlaybackRequest: playback ? {
      evidence:'playback_request_only',startMs:playback.startMs,endMs:playback.endMs,
      paddingMs:playback.paddingMs,rate:playback.rate,requestedAt:playback.requestedAt,status:playback.status,
    } : null};
  }
  return annotations;
}

export async function buildListeningReview(manifest, outputPath, options = {}) {
  if (!Array.isArray(manifest.clips) || !manifest.clips.length || manifest.clips.length > 8) throw Error('Expected 1–8 clips');
  const clips = [];
  for (const input of manifest.clips) {
    if (typeof input.id !== 'string' || !input.id || clips.some(clip => clip.id === input.id) || !Number.isFinite(input.sourceStartMs) || input.sourceStartMs < 0) throw Error('Invalid review clip');
    const buffer = await fs.readFile(input.file);
    if (buffer.length > 4 * 1024 * 1024) throw Error('Review clip exceeds 4 MiB');
    const summary = summarizeReviewWav(buffer);
    clips.push({ id: input.id, sourceStartMs: input.sourceStartMs, ...summary, sha256: createHash('sha256').update(buffer).digest('hex'), audio: `data:audio/wav;base64,${buffer.toString('base64')}` });
  }
  validateReviewRegions(manifest.regions, clips);
  const datasetId = createHash('sha256').update(JSON.stringify({clips:clips.map(({audio,peaks,...rest})=>rest),regions:manifest.regions})).digest('hex');
  const initialAnnotations = importReviewAnnotations(options.annotations, datasetId, clips, manifest.regions);
  const data = JSON.stringify({datasetId,clips,regions:manifest.regions,initialAnnotations}).replace(/</g,'\\u003c');
  const template = await fs.readFile(new URL('./listening-review.html', import.meta.url),'utf8');
  const output = path.resolve(outputPath);
  if (manifest.clips.some(clip=>path.resolve(clip.file)===output)) throw Error('Output cannot replace a source clip');
  await fs.mkdir(path.dirname(output),{recursive:true});
  await fs.writeFile(output,template.replace('/* REVIEW_DATA */',() => data));
  return {datasetId,clipCount:clips.length,regionCount:manifest.regions.length,output};
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  const [manifestPath, outputPath] = process.argv.slice(2);
  if (!manifestPath || !outputPath) throw Error('Usage: node build-listening-review.mjs manifest.json output.html');
  console.log(JSON.stringify(await buildListeningReview(JSON.parse(await fs.readFile(manifestPath,'utf8')),outputPath)));
}
